div.script:
document.getElementById('bundle-tnc-check').addEventListener('change', function() {
    var btn = document.getElementById('bundle-accept-btn');
    if (this.checked) {
        btn.classList.remove('pe-none', 'opacity-50');
        btn.removeAttribute('aria-disabled');
        btn.style.pointerEvents = '';
    } else {
        btn.classList.add('pe-none', 'opacity-50');
        btn.setAttribute('aria-disabled', 'true');
        btn.style.pointerEvents = 'none';
    }
});

t.script:
(function() {
    // ── Reactive Activate button ──────────────────────────
    function updateActivateBtn(modal) {
        var btn  = modal.querySelector('.wink-activate-submit');
        var hint = modal.querySelector('.wink-activate-hint');
        if (!btn) return;
        var reqEmp = btn.getAttribute('data-req-emp') === '1';
        var empSelected = modal.querySelectorAll('.wink-emp-checkbox:checked').length > 0;
        var newEmpInput = modal.querySelector('input[name="new_emp_name"]');
        var hasNewEmp = newEmpInput && newEmpInput.value.trim().length > 0;
        if (reqEmp && !empSelected && !hasNewEmp) {
            btn.disabled = true;
            if (hint) hint.classList.remove('d-none');
        } else {
            btn.disabled = false;
            if (hint) hint.classList.add('d-none');
        }
    }

    document.querySelectorAll('.modal[id^="wink-activate-modal-"]').forEach(function(m) {
        m.addEventListener('shown.bs.modal', function() { updateActivateBtn(m); });
        updateActivateBtn(m);
    });

    // ── Employee card toggle ──────────────────────────────
    document.querySelectorAll('.wink-emp-card').forEach(function(card) {
        var cb = card.querySelector('.wink-emp-checkbox');
        if (!cb) return;
        card.addEventListener('click', function() {
            cb.checked = !cb.checked;
            card.classList.toggle('selected', cb.checked);
            var modal = card.closest('.modal');
            if (modal) updateActivateBtn(modal);
        });
    });

    // ── Add New Employee toggle ───────────────────────────
    document.querySelectorAll('.wink-new-emp-toggle').forEach(function(btn) {
        btn.addEventListener('click', function() {
            var panel = document.querySelector(btn.getAttribute('data-target'));
            if (!panel) return;
            panel.classList.toggle('d-none');
            var nameInput = panel.querySelector('input[name="new_emp_name"]');
            if (nameInput && !nameInput._winkListening) {
                nameInput._winkListening = true;
                nameInput.addEventListener('input', function() {
                    var modal = nameInput.closest('.modal');
                    if (modal) updateActivateBtn(modal);
                });
            }
        });
    });

    // ── Auto-open modal after activation redirect ─────────
    var params = new URLSearchParams(window.location.search);
    var openModalId = params.get('open_modal');
    if (openModalId && typeof bootstrap !== 'undefined') {
        var modalEl = document.getElementById('wink-activate-modal-' + openModalId);
        if (modalEl) {
            var bsModal = new bootstrap.Modal(modalEl);
            modalEl.addEventListener('shown.bs.modal', function() {
                updateActivateBtn(modalEl);
            }, { once: true });
            bsModal.show();
        }
    }
})();

document.addEventListener('DOMContentLoaded', function () {
    var approveForm = document.querySelector('form[action*="/approve"]');
    if (approveForm) {
        approveForm.addEventListener('submit', function () {
            var btn = approveForm.querySelector('button[type="submit"]');
            if (btn) {
                btn.disabled = true;
                btn.style.minWidth = '180px';
                btn.innerHTML = ' Processing\u2026';
            }
        });
    }
});

div.script:
(function() {
    function updateActivateBtn(modal) {
        var btn  = modal.querySelector('.wink-activate-submit');
        var hint = modal.querySelector('.wink-activate-hint');
        if (!btn) return;
        var reqEmp = btn.getAttribute('data-req-emp') === '1';
        var empSelected = modal.querySelectorAll('.wink-emp-checkbox:checked').length > 0;
        var newEmpInput = modal.querySelector('input[name="new_emp_name"]');
        var hasNewEmp = newEmpInput && newEmpInput.value.trim().length > 0;
        if (reqEmp && !empSelected && !hasNewEmp) {
            btn.disabled = true;
            if (hint) hint.classList.remove('d-none');
        } else {
            btn.disabled = false;
            if (hint) hint.classList.add('d-none');
        }
    }

    document.querySelectorAll('.modal[id^="wink-bnd-modal-"]').forEach(function(m) {
        m.addEventListener('shown.bs.modal', function() { updateActivateBtn(m); });
        updateActivateBtn(m);
    });

    document.querySelectorAll('.wink-emp-card').forEach(function(card) {
        var cb = card.querySelector('.wink-emp-checkbox');
        if (!cb) return;
        card.addEventListener('click', function() {
            cb.checked = !cb.checked;
            card.classList.toggle('selected', cb.checked);
            var modal = card.closest('.modal');
            if (modal) {
                syncEmployeesToForm(modal);
                updateActivateBtn(modal);
            }
        });
    });

    function syncEmployeesToForm(modal) {
        if (!modal) return;
        var form = modal.querySelector('.wink-activate-form');
        if (!form) return;
        form.querySelectorAll('input[name="employee_ids"]').forEach(function(el) { el.remove(); });
        modal.querySelectorAll('.wink-emp-checkbox:checked').forEach(function(checked) {
            var hidden = document.createElement('input');
            hidden.type = 'hidden';
            hidden.name = 'employee_ids';
            hidden.value = checked.value;
            form.appendChild(hidden);
        });
    }

    // Toggle "Add New Employee" panel
    document.querySelectorAll('.wink-new-emp-toggle').forEach(function(btn) {
        btn.addEventListener('click', function() {
            var panel = document.querySelector(btn.getAttribute('data-target'));
            if (!panel) return;
            panel.classList.toggle('d-none');
            var nameInput = panel.querySelector('input[name="new_emp_name"]');
            if (nameInput && !nameInput._winkListening) {
                nameInput._winkListening = true;
                nameInput.addEventListener('input', function() {
                    var modal = nameInput.closest('.modal');
                    if (modal) updateActivateBtn(modal);
                });
            }
        });
    });

    // Auto-open modal if returning from activation redirect
    var params = new URLSearchParams(window.location.search);
    var openModalId = params.get('open_modal');
    if (openModalId && typeof bootstrap !== 'undefined') {
        var modalEl = document.getElementById('wink-bnd-modal-' + openModalId);
        if (modalEl) {
            var bsModal = new bootstrap.Modal(modalEl);
            modalEl.addEventListener('shown.bs.modal', function() {
                updateActivateBtn(modalEl);
            }, { once: true });
            bsModal.show();
        }
    }
})();
